    """Every number already rented gets its rental record.

    Their price was never kept - nothing read it before this - so it stays
    null rather than being guessed. Leased from when the row was created. A
    RELEASED row is one whose release failed, still billed, so it is open too.
    """
    GroupNumber = apps.get_model('sms', 'GroupNumber')
    NumberLease = apps.get_model('sms', 'NumberLease')
    NumberLease.objects.bulk_create([
        NumberLease(
            number=row.number,
            provider=row.provider,
            provider_number_id=row.provider_number_id,
            country=row.country,
            conversation_id=row.conversation_id,
            conversation_name=(
                row.conversation.name[:120] if row.conversation_id else ''
            ),
            leased_at=row.created_at,
        )
        for row in GroupNumber.objects.select_related('conversation')
    ])


